class Solution:
    def mergeInBetween(self, list1: ListNode, a: int, b: int, list2: ListNode) -> ListNode:
        prev = list1
        for _ in range(a - 1):
            prev = prev.next
        tail = prev
        for _ in range(b - a + 2):
            tail = tail.next
        prev.next = list2
        cur = list2
        while cur.next:
            cur = cur.next
        cur.next = tail
        return list1

